#!/bin/sh
# The entry point for hello-web's launcher, generated by claude-apps (/ship). POSIX sh, so it runs on a machine with no Node:
# it finds a Node 18 or newer, or downloads one (checked against nodejs.org's SHASUMS256.txt) into the plugin's data
# folder once, then runs session-start.mjs with the same arguments. A failure is said out loud, never swallowed.
PROJECT='hello-web'
NODE_VERSION="${SHIP_NODE_VERSION:-v22.12.0}"
DATA="${CLAUDE_PLUGIN_DATA:-$HOME/.claude-apps/$PROJECT}"
HERE=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
MODE="$1"

say() {
  # A SessionStart hook speaks JSON; the slash commands print plain text.
  if [ -z "$MODE" ]; then
    printf '{"systemMessage": "%s: %s"}\n' "$PROJECT" "$(printf '%s' "$1" | sed 's/["\\]/\\&/g')"
  else
    printf '%s: %s\n' "$PROJECT" "$1"
  fi
}
ok_node() {
  [ -x "$1" ] || return 1
  major=$("$1" -e 'process.stdout.write(process.versions.node.split(".")[0])' 2>/dev/null) || return 1
  [ "${major:-0}" -ge 18 ]
}
find_node() {
  for n in "$SHIP_NODE" "$DATA/node/bin/node" "$(command -v node 2>/dev/null)" /opt/homebrew/bin/node /usr/local/bin/node \
    "$HOME/.volta/bin/node" "$HOME/.local/share/mise/shims/node" "$HOME/.asdf/shims/node"; do
    if [ -n "$n" ] && ok_node "$n"; then echo "$n"; return 0; fi
  done
  for n in $(ls -d "$HOME"/.nvm/versions/node/*/bin/node "$HOME"/.fnm/node-versions/*/installation/bin/node 2>/dev/null | sort -r); do
    if ok_node "$n"; then echo "$n"; return 0; fi
  done
  return 1
}
download_node() {
  case "$(uname -s)" in Darwin) os=darwin ;; Linux) os=linux ;; *) say "no Node found, and this system ($(uname -s)) needs Node 18+ installed by hand: https://nodejs.org"; return 1 ;; esac
  case "$(uname -m)" in arm64|aarch64) arch=arm64 ;; x86_64|amd64) arch=x64 ;; *) say "no Node found for $(uname -m); install Node 18+ from https://nodejs.org"; return 1 ;; esac
  command -v curl >/dev/null 2>&1 || { say "no Node and no curl found; install Node 18+ from https://nodejs.org"; return 1; }
  name="node-$NODE_VERSION-$os-$arch.tar.gz"
  base="https://nodejs.org/dist/$NODE_VERSION"
  tmp="$DATA/node.download"
  rm -rf "$tmp" && mkdir -p "$tmp" || return 1
  if ! curl -fsSL --max-time 150 -o "$tmp/$name" "$base/$name" || ! curl -fsSL --max-time 20 -o "$tmp/SHASUMS256.txt" "$base/SHASUMS256.txt"; then
    rm -rf "$tmp"; say "could not download Node $NODE_VERSION from nodejs.org (offline?); it will try again next session"; return 1
  fi
  want=$(grep " $name\$" "$tmp/SHASUMS256.txt" | cut -d' ' -f1)
  if command -v shasum >/dev/null 2>&1; then got=$(shasum -a 256 "$tmp/$name" | cut -d' ' -f1); else got=$(sha256sum "$tmp/$name" | cut -d' ' -f1); fi
  if [ -z "$want" ] || [ "$want" != "$got" ]; then rm -rf "$tmp"; say "the Node download did not match its published checksum; not used"; return 1; fi
  mkdir -p "$tmp/x" && tar -xzf "$tmp/$name" -C "$tmp/x" --strip-components 1 || { rm -rf "$tmp"; say "could not unpack Node"; return 1; }
  rm -rf "$DATA/node" && mv "$tmp/x" "$DATA/node" && rm -rf "$tmp"
}

mkdir -p "$DATA"
NODE=$(find_node) || { download_node && NODE=$(find_node); } || exit 0
"$NODE" "$HERE/session-start.mjs" "$@" || say "the launcher failed (exit $?); /$PROJECT:open says more"
